func generate(numRows int) [][]int {
	res := [][]int{}
	for i := 0; i < numRows; i++ {
		row := make([]int, i+1) // 首尾是 1
		row[0], row[i] = 1, 1
		for j := 1; j < i; j++ {
			row[j] = res[i-1][j-1] + res[i-1][j]
		}
		res = append(res, row)
	}
	return res
}

